"""Actual red-zone UI and verified-play effects. Isolated data; no notifications sent."""
import json,os,threading
from pathlib import Path
from http.server import SimpleHTTPRequestHandler,ThreadingHTTPServer
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];OUT=Path(os.environ.get('DFL_LIVE_REVIEW_DIR',ROOT.parent/'dfl-live-review'));OUT.mkdir(parents=True,exist_ok=True)
head=(ROOT/'index.html').read_text().split('</head>')[0]+'</head>'
html=head+'''<body><main id="view" class="view" data-pulse-system="1" style="padding:16px"><h1>Live matchup</h1><div id="live-host"></div><ul class="gameday-players"></ul><div style="height:1000px"></div></main><script type="module">
import {mountLiveFootball} from './js/live-football.js';import {patchGameDay} from './js/game-day-dom.js';import {playerRows} from './js/game-day-player-rows.js';import {saveMode} from './js/theme.js';
const actual=Date.now;window.offset=0;Date.now=()=>actual()+offset;window.setTheme=saveMode;document.documentElement.dataset.uiMotion='on';
const wr={id:'7564',name:'Ja’Marr Chase',position:'WR',nflTeam:'CIN',roster:'1',isMine:true,points:16.4,state:'live',slot:'WR'},qb={id:'6770',name:'Joe Burrow',position:'QB',nflTeam:'CIN',roster:'1',isMine:true,points:20,state:'live',slot:'QB'},opp={id:'9',name:'Opponent running back',position:'RB',nflTeam:'PIT',roster:'2',points:10,state:'live'};
window.model={leagueId:'fixture',season:2026,week:7,memberId:1,completed:false,live:true,games:[{id:'7',sides:[{roster:'1',memberId:1,name:'My team',lineup:[wr,qb],bench:[]},{roster:'2',memberId:2,name:'Opponent',lineup:[opp],bench:[]}]}]};
window.makeFeed=()=>({game_id:'999',season:2026,week:7,fetched_at:new Date(Date.now()).toISOString(),snapshot:{id:'999',season:2026,week:7,live:true,offense:'CIN',redZone:true,goal:12,field:'PIT 12',down:'3rd & 4',clock:'4:12',period:3,lastPlay:'Joe Burrow pass to Ja’Marr Chase for 12 yards.',sides:[{id:'4',code:'CIN'},{id:'23',code:'PIT'}]},plays:[]});window.feeds=[makeFeed()];window.loads=0;window.loadFail=false;
window.play=(id,kind='touchdown',patch={})=>({id,gameId:'999',sequence:Number(id),at:Date.now()-50,eligible:true,kind,yards:42,text:'Joe Burrow pass to Ja’Marr Chase for 42 yards, TOUCHDOWN.',players:[{...wr,role:'receiver'},{...qb,role:'passer'}],...patch});feeds[0].plays=[play('1','touchdown',{at:Date.now()-5000})];
document.querySelector('ul').innerHTML=playerRows([wr,qb,opp]);window.wire=()=>mountLiveFootball(document.querySelector('#view'),{getModel:()=>model,getHost:()=>document.querySelector('#live-host'),getGameId:()=>model.games[0].id,getMotion:()=>document.documentElement.dataset.uiMotion!=='off',load:async()=>{loads++;if(loadFail)throw Error('Fixture offline');return structuredClone(feeds)}});window.live=wire();window.update=()=>live.update();window.parentPaint=()=>patchGameDay(document.querySelector('#live-host'),'<div data-football-panel></div>');await update();window.toastCount=0;new MutationObserver(rs=>{for(const r of rs)for(const n of r.addedNodes)if(n.matches?.('.nfl-play-toast'))toastCount++}).observe(document.body,{childList:true});window.ready=true;
</script></body></html>'''
class Handler(SimpleHTTPRequestHandler):
 def __init__(self,*a,**kw):super().__init__(*a,directory=str(ROOT),**kw)
 def do_GET(self):
  path=self.path.split('?')[0];body=html if path=='/live-review.html' else "export const db=()=>{throw Error('No real database in live review')};" if path=='/js/supabase.js' else "export const currentMember=()=>null;" if path=='/js/members.js' else None
  if body is not None:self.send_response(200);self.send_header('Content-Type','text/html' if path.endswith('html') else 'text/javascript');self.end_headers();self.wfile.write(body.encode());return
  super().do_GET()
 def log_message(self,*a):pass
server=ThreadingHTTPServer(('127.0.0.1',0),Handler);threading.Thread(target=server.serve_forever,daemon=True).start();base=f'http://127.0.0.1:{server.server_port}'
checks=[];errors=[]
def check(name,ok):
 checks.append({'check':name,'pass':bool(ok)});(OUT/'checks.json').write_text(json.dumps(checks,indent=2));assert ok,name;print('PASS '+name,flush=True)
